function makeMock(mode, delay = 0) {
  return async function mockFetch(path) {
    if (delay > 0) await new Promise(resolve => setTimeout(resolve, delay));
    if (mode === "network") throw new Error("offline");
    if (path !== "/products.json" || mode === "http") {
      return { status: 404, ok: false };
    }
    const body = mode === "data" ? "{" : JSON.stringify({ items: mode === "empty" ? [] : seed });
    return { status: 200, ok: true, json: async () => JSON.parse(body) };
  };
}

function startPage() {
  const source = document.querySelector("#source");
  const query = document.querySelector("#query");
  const category = document.querySelector("#category");
  const button = document.querySelector("#load");
  const status = document.querySelector("#status");
  const list = document.querySelector("#items");
  let items = [];
  let loading = false;
  let error = "";

  function render() {
    const matches = filterItems(items, query.value, category.value);
    const state = viewState({ loading, error, items: matches });
    list.replaceChildren();
    if (state === "loading") status.textContent = "جارٍ تحميل المنتجات…";
    if (state === "error") status.textContent = error;
    if (state === "empty") {
      status.textContent = items.length === 0 ? "الكتالوج فارغ." : "لا توجد نتائج تطابق البحث.";
    }
    if (state === "ready") {
      status.textContent = "عدد النتائج: " + matches.length;
      for (const item of matches) {
        const row = document.createElement("li");
        row.textContent = item.name + " | " + item.category;
        list.append(row);
      }
    }
  }

  async function reload() {
    if (loading) return;
    const request = source.value === "file" ? fetch : makeMock(source.value, 500);
    loading = true;
    items = [];
    error = "";
    source.disabled = query.disabled = category.disabled = button.disabled = true;
    category.replaceChildren(new Option("كل الفئات", ""));
    render();

    const result = await loadCatalogue(request);
    items = result.items;
    error = result.error;
    for (const name of new Set(items.map(item => item.category))) {
      category.add(new Option(name, name));
    }
    loading = false;
    source.disabled = query.disabled = category.disabled = button.disabled = false;
    render();
  }

  query.addEventListener("input", render);
  category.addEventListener("change", render);
  button.addEventListener("click", reload);
  reload();
}

